"""Deterministic synthetic market data.

Set ``data_provider="synthetic"`` to run the whole pipeline with no network at
all. This exists for three concrete reasons:

* **CI.** Tests must assert on agent behaviour, not on whatever Reliance did
  this morning. A fixed seed gives a fixed tape and therefore a fixed decision.
* **Air-gapped and rate-limited environments.** Free data endpoints fail; the
  framework should still be demonstrable when they do.
* **Reproducible documentation.** The sample run in the README is generated by
  this provider, so anyone can reproduce it byte for byte.

The generated series is a geometric random walk with a configurable drift and
volatility, plus realistic intrabar structure and a volume series correlated
with range. It is *not* a market simulator and nothing here should be used to
validate a strategy - a random walk has no edge to find.
"""

from __future__ import annotations

import hashlib
from datetime import timedelta
from typing import Any

import numpy as np
import pandas as pd

from tradingagents_in.dataflows.calendar_in import is_trading_day, session_context
from tradingagents_in.dataflows.corporate_actions import CorporateAction
from tradingagents_in.dataflows.indicators import compute_all
from tradingagents_in.dataflows.microstructure import build_microstructure
from tradingagents_in.dataflows.news import NewsItem
from tradingagents_in.dataflows.symbols import resolve
from tradingagents_in.models.analyst import (
    FlowSnapshot,
    MacroIndicator,
    PeerMetric,
    SentimentSource,
)
from tradingagents_in.utils.timeutils import IST, now_ist

# A tape with a mild uptrend and 24% annualised vol - an ordinary Nifty
# large-cap, neither a bubble nor a falling knife.
DEFAULT_ANNUAL_DRIFT = 0.12
DEFAULT_ANNUAL_VOL = 0.24


def _rng(symbol: str, seed: int | None) -> np.random.Generator:
    """Per-symbol deterministic generator, so TCS and INFY differ but repeat."""
    if seed is None:
        digest = hashlib.sha256(symbol.encode()).hexdigest()[:8]
        seed = int(digest, 16)
    return np.random.default_rng(seed)


def synthetic_ohlcv(
    symbol: str,
    bars: int = 400,
    start_price: float = 2_500.0,
    interval: str = "1d",
    seed: int | None = None,
    annual_drift: float = DEFAULT_ANNUAL_DRIFT,
    annual_vol: float = DEFAULT_ANNUAL_VOL,
) -> pd.DataFrame:
    """A deterministic OHLCV frame in the same shape the real feed returns."""
    rng = _rng(f"{symbol}:{interval}", seed)

    periods_per_year = {"1d": 252, "1h": 252 * 6, "15m": 252 * 25}.get(interval, 252)
    dt = 1 / periods_per_year
    mu = (annual_drift - 0.5 * annual_vol**2) * dt
    sigma = annual_vol * np.sqrt(dt)

    returns = rng.normal(mu, sigma, bars)
    closes = start_price * np.exp(np.cumsum(returns))

    # Intrabar structure: the open gaps modestly from the previous close, and
    # the high/low straddle the body by a fraction of the period's range.
    opens = np.empty(bars)
    opens[0] = start_price
    opens[1:] = closes[:-1] * (1 + rng.normal(0, sigma * 0.3, bars - 1))
    body_high = np.maximum(opens, closes)
    body_low = np.minimum(opens, closes)
    wick = np.abs(rng.normal(0, sigma * 0.6, bars)) * closes
    highs = body_high + wick
    lows = np.maximum(body_low - wick, 0.01)

    # Volume rises with range: quiet days are narrow, wide days are heavy.
    ranges = (highs - lows) / closes
    base_volume = 3_000_000 if interval == "1d" else 250_000
    volumes = (base_volume * (1 + 4 * ranges / max(ranges.mean(), 1e-9))
               * rng.lognormal(0, 0.25, bars)).astype(int)

    index = _index_for(bars, interval)
    return pd.DataFrame(
        {"open": opens, "high": highs, "low": lows, "close": closes, "volume": volumes},
        index=index,
    )


def _index_for(bars: int, interval: str) -> pd.DatetimeIndex:
    """Timestamps on real Indian trading sessions, newest last."""
    end = now_ist().replace(second=0, microsecond=0)
    if interval == "1d":
        days: list[pd.Timestamp] = []
        cursor = end.date()
        while len(days) < bars:
            if is_trading_day(cursor):
                days.append(pd.Timestamp(cursor, tz=IST) + pd.Timedelta(hours=15, minutes=30))
            cursor -= timedelta(days=1)
        return pd.DatetimeIndex(sorted(days), name="datetime")

    step = pd.Timedelta(hours=1) if interval == "1h" else pd.Timedelta(minutes=15)
    stamps: list[pd.Timestamp] = []
    cursor = pd.Timestamp(end).tz_convert(IST) if end.tzinfo else pd.Timestamp(end, tz=IST)
    while len(stamps) < bars:
        if is_trading_day(cursor.date()) and 9 <= cursor.hour <= 15:
            stamps.append(cursor)
        cursor -= step
    return pd.DatetimeIndex(sorted(stamps), name="datetime")


def build_synthetic_bundle(symbol: str, config: dict[str, Any] | None = None) -> Any:
    """A fully-populated :class:`MarketBundle` with no network access."""
    from tradingagents_in.dataflows.toolkit import MarketBundle  # noqa: PLC0415 - cycle

    config = config or {}
    seed = config.get("synthetic_seed")
    ref = resolve(symbol)
    exchange = ref.exchange.value if hasattr(ref.exchange, "value") else str(ref.exchange)
    bundle = MarketBundle(ref=ref, session=session_context(exchange=exchange))

    start_price = 24_000.0 if ref.is_index else 2_500.0
    timeframes = list(config.get("technical_timeframes", ["1d", "1h", "15m"]))
    if "1d" not in timeframes:
        timeframes.insert(0, "1d")

    for tf in timeframes:
        bars = {"1d": 400, "1h": 300, "15m": 250}.get(tf, 300)
        frame = synthetic_ohlcv(
            ref.base_symbol, bars=bars, start_price=start_price, interval=tf, seed=seed
        )
        bundle.prices[tf] = frame
        bundle.enriched[tf] = compute_all(frame, intraday=tf not in ("1d", "1wk"))

    daily = bundle.prices["1d"]
    last = float(daily["close"].iloc[-1])
    prev = float(daily["close"].iloc[-2])
    bundle.quote = {
        "last_price": round(last, 2),
        "previous_close": round(prev, 2),
        "change_pct": round((last - prev) / prev * 100, 2),
        "day_high": round(float(daily["high"].iloc[-1]), 2),
        "day_low": round(float(daily["low"].iloc[-1]), 2),
        "year_high": round(float(daily["high"].tail(252).max()), 2),
        "year_low": round(float(daily["low"].tail(252).min()), 2),
        "volume": int(daily["volume"].iloc[-1]),
        "source": "synthetic",
    }
    bundle.benchmark = synthetic_ohlcv("NIFTY50", bars=400, start_price=24_000.0, seed=seed)

    if not ref.is_index:
        bundle.fundamentals = _synthetic_fundamentals(ref, last, seed)
        bundle.peers = _synthetic_peers(ref, seed)
        bundle.corporate_actions = _synthetic_actions(ref)

    bundle.news_items = _synthetic_news(ref)
    bundle.company_news = [n for n in bundle.news_items if ref.base_symbol.title() in n.title]
    bundle.sentiment_sources = _synthetic_sentiment(ref, seed)
    bundle.macro_indicators = _synthetic_macro()
    bundle.india_indicators = _synthetic_india_indicators()
    bundle.flows = _synthetic_flows()
    bundle.upcoming_events = [
        f"Weekly F&O expiry on {bundle.session.weekly_expiry}",
        f"Monthly F&O expiry on {bundle.session.monthly_expiry}",
        "RBI Monetary Policy Committee decision (bi-monthly cycle)",
        "Quarterly results season for Nifty 50 constituents",
    ]
    bundle.micro = build_microstructure(ref, bundle.quote, daily, 0.35, config)

    bundle.sources_used = [
        "prices", "quote", "benchmark", "fundamentals", "peers",
        "corporate_actions", "news", "sentiment", "macro", "flows", "microstructure",
    ]
    if ref.is_index:
        for gone in ("fundamentals", "peers", "corporate_actions"):
            bundle.sources_used.remove(gone)
    bundle.elapsed_seconds = 0.0
    return bundle


# ------------------------------------------------------------------ pieces
def _synthetic_fundamentals(ref: Any, price: float, seed: int | None) -> dict[str, Any]:
    rng = _rng(f"{ref.base_symbol}:fundamentals", seed)
    shares = 6.5e9
    market_cap = price * shares
    pe = float(rng.uniform(18, 32))
    pat = market_cap / pe
    return {
        "name": f"{ref.base_symbol.title()} Limited",
        "sector": ref.sector,
        "industry": ref.sector,
        "market_cap_inr": round(market_cap, 2),
        "pe": round(pe, 2),
        "forward_pe": round(pe * float(rng.uniform(0.85, 0.98)), 2),
        "pb": round(float(rng.uniform(2.0, 5.5)), 2),
        "ev_to_ebitda": round(float(rng.uniform(9, 18)), 2),
        "dividend_yield_pct": round(float(rng.uniform(0.3, 1.8)), 2),
        "roe_pct": round(float(rng.uniform(11, 24)), 2),
        "roce_pct": round(float(rng.uniform(12, 26)), 2),
        "operating_margin_pct": round(float(rng.uniform(14, 28)), 2),
        "debt_to_equity": round(float(rng.uniform(0.1, 0.9)), 2),
        "interest_coverage": round(float(rng.uniform(3, 12)), 2),
        "current_ratio": round(float(rng.uniform(0.9, 2.1)), 2),
        "net_debt_inr": round(market_cap * float(rng.uniform(0.02, 0.25)), 2),
        "operating_cash_flow_inr": round(pat * float(rng.uniform(1.1, 1.6)), 2),
        "free_cash_flow_inr": round(pat * float(rng.uniform(0.4, 1.0)), 2),
        "ocf_to_pat": round(float(rng.uniform(0.8, 1.5)), 2),
        "sales_growth_3y_cagr_pct": round(float(rng.uniform(4, 18)), 2),
        "profit_growth_3y_cagr_pct": round(float(rng.uniform(2, 22)), 2),
        "beta": round(float(rng.uniform(0.7, 1.3)), 2),
        "book_value": round(price / float(rng.uniform(2.0, 5.5)), 2),
        "held_by_insiders_pct": round(float(rng.uniform(35, 62)), 2),
        "held_by_institutions_pct": round(float(rng.uniform(18, 40)), 2),
        "quarters": _synthetic_quarters(pat, rng),
        "sources": ["synthetic"],
    }


def _synthetic_quarters(pat: float, rng: np.random.Generator) -> list[dict[str, Any]]:
    quarters = []
    for i, label in enumerate(("Q2 FY26", "Q1 FY26", "Q4 FY25", "Q3 FY25")):
        decay = 1 - 0.03 * i
        revenue = pat * float(rng.uniform(5, 8)) * decay
        quarters.append(
            {
                "period": label,
                "revenue_inr": round(revenue, 2),
                "pat_inr": round(pat / 4 * decay, 2),
                "ebitda_margin_pct": round(float(rng.uniform(15, 26)), 2),
                "revenue_yoy_pct": round(float(rng.uniform(-4, 20)), 2),
                "pat_yoy_pct": round(float(rng.uniform(-10, 28)), 2),
                "is_consolidated": True,
            }
        )
    return quarters


def _synthetic_peers(ref: Any, seed: int | None) -> list[PeerMetric]:
    from tradingagents_in.config.universe import INDEX_CONSTITUENTS, sector_for

    rng = _rng(f"{ref.base_symbol}:peers", seed)
    pool = [
        s for s in INDEX_CONSTITUENTS.get("NIFTY50", ())
        if sector_for(s) == ref.sector and s != ref.base_symbol
    ][:5]
    return [
        PeerMetric(
            symbol=f"{s}.NS",
            name=s.title(),
            pe=round(float(rng.uniform(15, 35)), 2),
            pb=round(float(rng.uniform(1.5, 6.0)), 2),
            roe_pct=round(float(rng.uniform(9, 26)), 2),
            debt_to_equity=round(float(rng.uniform(0.05, 1.2)), 2),
            market_cap_inr=round(float(rng.uniform(0.5, 12)) * 1e12, 2),
            revenue_growth_yoy_pct=round(float(rng.uniform(-3, 22)), 2),
        )
        for s in pool
    ]


def _synthetic_actions(ref: Any) -> list[CorporateAction]:
    today = now_ist().date()
    return [
        CorporateAction(
            action_type="DIVIDEND",
            ex_date=today - timedelta(days=95),
            detail="Final dividend of Rs 10 per share",
            amount=10.0,
            source="synthetic",
        )
    ]


def _synthetic_news(ref: Any) -> list[NewsItem]:
    name = ref.base_symbol.title()
    now = now_ist()
    headlines = [
        (f"{name} reports steady quarterly revenue growth, margin holds", "Economic Times"),
        (f"Brokerages retain positive view on {name} after results call", "Moneycontrol"),
        ("Nifty ends higher as banking and IT stocks lead the advance", "Business Standard"),
        ("FIIs turn net buyers in the cash segment for a third session", "LiveMint"),
        ("RBI keeps repo rate unchanged, retains neutral stance", "Economic Times"),
        ("Crude eases below $80 as supply concerns fade", "BusinessLine"),
        (f"{name} board approves capex for capacity expansion", "Moneycontrol"),
        ("GST collections cross Rs 1.8 lakh crore in the month", "Business Standard"),
    ]
    return [
        NewsItem(
            title=title,
            link=f"https://example.invalid/{i}",
            published=now - timedelta(hours=6 * i),
            source=source,
        )
        for i, (title, source) in enumerate(headlines)
    ]


def _synthetic_sentiment(ref: Any, seed: int | None) -> list[SentimentSource]:
    rng = _rng(f"{ref.base_symbol}:sentiment", seed)
    return [
        SentimentSource(
            source="Indian financial press",
            score=round(float(rng.uniform(-0.3, 0.5)), 3),
            volume=int(rng.integers(8, 30)),
            notes="ET, Moneycontrol, Business Standard, Mint headlines",
        ),
        SentimentSource(
            source="StockTwits",
            score=round(float(rng.uniform(-0.5, 0.7)), 3),
            volume=int(rng.integers(10, 60)),
            notes="Retail message volume",
        ),
        SentimentSource(
            source="Reddit r/IndiaInvestments",
            score=round(float(rng.uniform(-0.4, 0.4)), 3),
            volume=int(rng.integers(3, 20)),
            notes="Long-horizon retail discussion",
        ),
    ]


def _synthetic_macro() -> list[MacroIndicator]:
    return [
        MacroIndicator(name="nifty", value=24_180.0, change_pct=0.35, direction="up",
                       implication_for_india="Index holding above its 20-DMA"),
        MacroIndicator(name="usdinr", value=86.4, change_pct=-0.12, direction="down",
                       implication_for_india="A softer rupee helps IT and pharma exporters, "
                                             "hurts oil marketing and capital goods importers"),
        MacroIndicator(name="brent_crude", value=78.2, change_pct=-1.1, direction="down",
                       implication_for_india="Lower crude eases the import bill and CPI"),
        MacroIndicator(name="sp500", value=6_120.0, change_pct=0.42, direction="up",
                       implication_for_india="Constructive global cue for the Indian open"),
        MacroIndicator(name="india_vix", value=12.8, change_pct=-3.4, direction="down",
                       implication_for_india="Low volatility favours trend continuation over "
                                             "mean reversion"),
    ]


def _synthetic_india_indicators() -> list[MacroIndicator]:
    return [
        MacroIndicator(name="repo_rate", value=6.0, direction="unchanged",
                       implication_for_india="Neutral stance; rate-sensitive sectors have no "
                                             "fresh trigger"),
        MacroIndicator(name="cpi_inflation", value=4.3, direction="easing",
                       implication_for_india="Inside the RBI's tolerance band"),
        MacroIndicator(name="monsoon_vs_lpa_pct", value=103.0, direction="above normal",
                       implication_for_india="Supports rural demand and the kharif sowing "
                                             "outlook"),
        MacroIndicator(name="gst_collections_inr_cr", value=181_000.0, direction="up",
                       implication_for_india="Consumption momentum intact"),
    ]


def _synthetic_flows() -> FlowSnapshot:
    from tradingagents_in.dataflows.macro import interpret_flows

    snapshot = FlowSnapshot(
        date=str(now_ist().date()),
        fii_net_inr_cr=1_240.0,
        dii_net_inr_cr=860.0,
        fii_5d_net_inr_cr=3_180.0,
        dii_5d_net_inr_cr=2_450.0,
        fii_fno_index_futures_net_inr_cr=520.0,
    )
    snapshot.interpretation = interpret_flows(snapshot)
    return snapshot
